function openGrammarOverlay(topicKey) {
    if (!topicKey) return;
    
    // Convert table header text to internal key
    let key = topicKey;
    if (topicKey === 'mazi' || topicKey === 'Mazi (Geçmiş Zaman)') key = 'mazi';
    else if (topicKey === 'Menfi Mazi (ما)') key = 'ma';
    else if (topicKey === 'İnkari Mazi / Dua (لا)') key = 'la_mazi';
    else if (topicKey === 'Cehd-i Mutlak (لَمْ / Geçmiş Anlamı)') key = 'lam';
    else if (topicKey === 'muzari' || topicKey === 'Muzari (Şimdiki / Geniş Zaman)') key = 'muzari';
    else if (topicKey === 'Menfi Muzari (Olumsuz)') key = 'la_muzari';
    else if (topicKey === 'emir' || topicKey === 'Emir (Buyruk)') key = 'emir';
    else if (topicKey === 'Nehiy (Olumsuz Emir)') key = 'nehiy';

    const data = GramerVerileri[key];
    if (!data) return;

    let overlay = document.getElementById('grammar-overlay');
    if (!overlay) {
        // If not exists in HTML yet, create it dynamically
        overlay = document.createElement('div');
        overlay.id = 'grammar-overlay';
        overlay.className = 'grammar-overlay';
        overlay.style.cssText = 'position: fixed; top: 0; left: 0; width: 100vw; height: 100vh; background: white; z-index: 99999; display: none; flex-direction: column; opacity: 0; transition: opacity 0.3s ease;';
        
        overlay.innerHTML = `
            <div class="grammar-modal" style="width: 100%; height: 100%; transform: translateY(100vh); transition: transform 0.4s cubic-bezier(0.25, 0.8, 0.25, 1); display: flex; flex-direction: column; overflow: hidden; background-color: #fafafa; direction: ltr; text-align: left;">
                <div style="background: #2c3e50; padding: 25px 40px; display: flex; justify-content: space-between; align-items: center; box-shadow: 0 4px 10px rgba(0,0,0,0.15); z-index: 2;">
                    <h2 class="grammar-title" style="margin: 0; font-size: 38px; font-weight: normal; color: #ecf0f1; font-family: 'Inter', sans-serif;">Gramer Detayı</h2>
                    <button class="grammar-close-btn" onclick="closeGrammarOverlay()" style="background: rgba(255,255,255,0.15); border: none; font-size: 48px; color: #ecf0f1; cursor: pointer; width: 60px; height: 60px; border-radius: 50%; display: flex; justify-content: center; align-items: center; transition: background 0.2s;">&times;</button>
                </div>
                <div class="grammar-content-container" style="padding: 50px; overflow-y: auto; flex-grow: 1; max-width: 1400px; margin: 0 auto; width: 100%; box-sizing: border-box;">
                </div>
            </div>
        `;
        document.body.appendChild(overlay);

        overlay.addEventListener('click', function(e) {
            if (e.target.id === 'grammar-overlay') {
                closeGrammarOverlay();
            }
        });
    }

    const contentDiv = overlay.querySelector('.grammar-content-container');
    const titleDiv = overlay.querySelector('.grammar-title');
    
    if (contentDiv) {
        titleDiv.innerHTML = data.title;
        contentDiv.innerHTML = data.content;
    }

    overlay.style.display = 'flex';
    // Animation
    setTimeout(() => {
        overlay.style.opacity = '1';
        overlay.querySelector('.grammar-modal').style.transform = 'translateY(0)';
    }, 10);
}

function closeGrammarOverlay(event) {
    if (event) {
        if (!event.target.classList.contains('grammar-overlay') && !event.target.classList.contains('grammar-close-btn')) {
            return;
        }
    }
    const overlay = document.getElementById('grammar-overlay');
    if (overlay) {
        overlay.querySelector('.grammar-modal').style.transform = 'translateY(100vh)';
        setTimeout(() => {
            overlay.style.opacity = '0';
        }, 100);
        setTimeout(() => {
            overlay.style.display = 'none';
        }, 400);
    }
}

