window.selectVerbForGame = function(cat, verb, btnElement) {
    window.CurrentGameVerbs[cat] = verb;
    
    // Butonları resetle
    let btns = document.querySelectorAll('.verb-btn-' + cat);
    btns.forEach(b => {
        b.style.background = '#95a5a6';
        b.style.transform = 'scale(1)';
    });
    // Aktif butonu vurgula
    btnElement.style.background = '#27ae60';
    btnElement.style.transform = 'scale(1.1)';
    
    // Tablodaki hücreleri ek (suffix) haline geri getir
    let cells = document.querySelectorAll('#game-table-' + cat + ' .game-cell');
    cells.forEach(cell => {
        let suffix = cell.getAttribute('data-suffix');
        cell.innerHTML = '<span class="grammar-arabic-text" style="font-size: 65px; font-weight: normal !important; color: #e74c3c;">' + suffix + '</span>';
        cell.style.background = 'transparent';
    });
    
    if(typeof SoundEngine !== "undefined") SoundEngine.playClick();
};

window.playGameCell = function(cat, idx, cell) {
    let currentVerb = window.CurrentGameVerbs[cat];
    if (!currentVerb) {
        alert("Lütfen önce yukarıdan bir fiil seçin!");
        return;
    }
    
    // İlgili çekimi bul
    let word = InteractiveData[cat][currentVerb][idx];
    
    // Hücreye yazdır ve efekt ekle
    cell.innerHTML = '<span class="grammar-arabic-text" style="font-size: 65px; font-weight: normal !important; color: #2c3e50;">' + word + '</span>';
    cell.style.background = '#d4edda';
    
    if(typeof SoundEngine !== "undefined") SoundEngine.playSuccess();
};
